import{at as e,it as t,n,vt as r}from"./chunks/framework.B6nQ8gjX.js";var i=JSON.parse(`{"title":"JNTemplate","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1617980950000}`),a={name:`index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="jntemplate" tabindex="-1">JNTemplate <a class="header-anchor" href="#jntemplate" aria-label="Permalink to “JNTemplate”">​</a></h1><p><a href="https://travis-ci.org/jiniannet/jntemplate" target="_blank" rel="noreferrer"><img src="https://travis-ci.org/jiniannet/jntemplate.svg?branch=master" alt="Build Status"></a><a href="https://www.nuget.org/packages/JinianNet.JNTemplate/" target="_blank" rel="noreferrer"><img src="https://img.shields.io/nuget/v/JinianNet.JNTemplate.svg" alt="GitHub stars"></a><a href="https://github.com/jiniannet/jntemplate/stargazers" target="_blank" rel="noreferrer"><img src="https://img.shields.io/github/stars/jiniannet/jntemplate.svg" alt="GitHub stars"></a><a href="https://raw.githubusercontent.com/jiniannet/jntemplate/master/License.txt" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/license-Mit-blue.svg" alt="GitHub license"></a><a href="https://github.com/jiniannet/jntemplate/issues" target="_blank" rel="noreferrer"><img src="https://img.shields.io/github/issues/jiniannet/jntemplate.svg" alt="GitHub issues"></a></p><blockquote><p>A cross-platform, high-performance and highly flexible text parsing engine (template engine).</p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>JNTemplate is a text parsing engine (template engine) written entirely in C#. It can generate any text-based content, including but not limited to HTML, XML and CSS, keeping the presentation layer separate from back-end code logic. It also gives you an alternative to WebForms and Razor!</p><p>All of the JNTemplate source code is open source and has minimal dependencies, which makes migration and cross-platform support easy. Under the terms of our open source license, you are free to use, distribute and build commercial products with it (see License.txt for details).</p><p>Since version 2.0, the engine has been fully upgraded to a compiled template engine and can run on .NET Framework, Mono, .NET Core and .NET 5.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to “Features”">​</a></h2><ul><li>Faster: an efficient IL-based template pre-compilation mechanism brings runtime speed close to native code.</li><li>Simpler: an easy-to-learn syntax — with some front-end/back-end background you can get started in as little as 10 minutes.</li><li>More convenient: every option can be configured freely, and you can extend the engine with your own tags.</li><li>Freer: free for commercial use with no fees at all, and all source code is fully open.</li></ul><h2 id="donation" tabindex="-1">Donation <a class="header-anchor" href="#donation" aria-label="Permalink to “Donation”">​</a></h2><p>If you find JNTemplate helpful, <a href="https://gitee.com/jiniannet/jntemplate" target="_blank" rel="noreferrer">donations are welcome</a>. Or just give us a star.</p><h3 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to “License”">​</a></h3><p>Since V1.4.0, jntemplate is licensed under the MIT license! <a href="./guide/license.html">Read more</a></p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};